func (w oidcSessionWhereR[Q]) HasMember(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Members.NameExpr()),
		sm.Where(Members.Columns.ID.EQ(w.cols.MemberID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *OidcSession) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Member":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("oidcSession cannot load %T as %q", retrieved, name)
		}

		o.R.Member = rel
		o.R.Loaded.Member = true

		if rel != nil {
			rel.R.OidcSessions = OidcSessionSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("oidcSession has no relationship %q", name)
	}
}

type oidcSessionPreloader struct {
	Member func(...psql.PreloadOption) psql.Preloader
}

func buildOidcSessionPreloader() oidcSessionPreloader {
	return oidcSessionPreloader{
		Member: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "Member",
				Sides: []psql.PreloadSide{
					{
						From:        OidcSessions,
						To:          Members,
						FromColumns: []string{"member_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
	}
}

type oidcSessionThenLoader[Q orm.Loadable] struct {
	Member func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildOidcSessionThenLoader[Q orm.Loadable]() oidcSessionThenLoader[Q] {
	type MemberLoadInterface interface {
		LoadMember(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return oidcSessionThenLoader[Q]{
		Member: thenLoadBuilder[Q](
			"Member",
			func(ctx context.Context, exec bob.Executor, retrieved MemberLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMember(ctx, exec, mods...)
			},
		),
	}
}

// LoadMember loads the oidcSession's Member into the .R struct
func (o *OidcSession) LoadMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Member = nil
	o.R.Loaded.Member = false

	related, err := o.Member(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.OidcSessions = OidcSessionSlice{o}

	o.R.Member = related
	o.R.Loaded.Member = true
	return nil
}

// LoadMember loads the oidcSession's Member into the .R struct
func (os OidcSessionSlice) LoadMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.Member(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Member = nil
		o.R.Loaded.Member = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	oidcSessionByKey := make(map[uuid.UUID][]*OidcSession, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		oidcSessionByKey[o.MemberID] = append(oidcSessionByKey[o.MemberID], o)
	}

	for _, rel := range members {

		owners, ok := oidcSessionByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Member != nil {
				continue
			}

			rel.R.OidcSessions = append(rel.R.OidcSessions, o)

			o.R.Member = rel

		}
	}

	return nil
}

type oidcSessionJoins[Q dialect.Joinable] struct {
	typ    string
	Member modAs[Q, memberColumns]
}

func (j oidcSessionJoins[Q]) aliasedAs(alias string) oidcSessionJoins[Q] {
	return buildOidcSessionJoins[Q](buildOidcSessionColumns(alias), j.typ)
}

func buildOidcSessionJoins[Q dialect.Joinable](cols oidcSessionColumns, typ string) oidcSessionJoins[Q] {
	return oidcSessionJoins[Q]{
		typ: typ,
		Member: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MemberID),
					))
				}

				return mods
			},
		},
	}
}
